【主要应用】线性递推加速、图上游走计数、矩阵求逆、斐波那契数列。
【应用方式】将递推式写成矩阵形式，用矩阵快速幂加速；图邻接矩阵的 k 次幂表示走 k 步方案数；矩阵求逆用高斯消元。
【模板代码】
```cpp
// 矩阵快速幂
struct Matrix {
    int a[N][N];
    Matrix() { memset(a, 0, sizeof(a)); }
};
Matrix mul(Matrix x, Matrix y, int n) {
    Matrix z;
    for (int i = 0; i < n; i++)
        for (int k = 0; k < n; k++)
            if (x.a[i][k])
                for (int j = 0; j < n; j++)
                    z.a[i][j] = (z.a[i][j] + 1LL * x.a[i][k] * y.a[k][j]) % MOD;
    return z;
}
Matrix qpow(Matrix a, long long b, int n) {
    Matrix res;
    for (int i = 0; i < n; i++) res.a[i][i] = 1;
    while (b) {
        if (b & 1) res = mul(res, a, n);
        a = mul(a, a, n);
        b >>= 1;
    }
    return res;
}
```

