// 线性基插入
void insert(long long x) {
    for (int i = 60; i >= 0; i--) {
        if (!(x >> i & 1)) continue;
        if (!p[i]) { p[i] = x; break; }
        x ^= p[i];
    }
}
// 查询最大值
long long query_max() {
    long long res = 0;
    for (int i = 60; i >= 0; i--)
