// 最小圈（二分 + SPFA 判负环）
bool check(double mid) {
    for (int i = 1; i <= n; i++) dis[i] = 0, vis[i] = 1;
    queue<int> q;
    for (int i = 1; i <= n; i++) q.push(i);
