// 线性筛莫比乌斯函数
int mu[N], primes[N], cnt;
bool vis[N];
void sieve(int n) {
    mu[1] = 1;
    for (int i = 2; i <= n; i++) {
        if (!vis[i]) primes[++cnt] = i, mu[i] = -1;
        for (int j = 1; j <= cnt && i * primes[j] <= n; j++) {
            vis[i * primes[j]] = true;
            if (i % primes[j] == 0) { mu[i * primes[j]] = 0; break; }
            mu[i * primes[j]] = -mu[i];
        }
    }
}
// 莫比乌斯反演 + 整除分块
long long solve(int n, int m) {
    long long ans = 0;
    for (int l = 1, r; l <= min(n, m); l = r + 1) {
        r = min(n / (n / l), m / (m / l));
        ans += (sum_mu[r] - sum_mu[l-1]) * (n / l) * (m / l);
    }
    return ans;
}
