// 杜教筛求 μ 前缀和
unordered_map<int, int> mp;
int sum_mu(int n) {
    if (n < N) return mu[n];
    if (mp.count(n)) return mp[n];
    int ans = 1;
    for (int l = 2, r; l <= n; l = r + 1) {
        r = n / (n / l);
        ans -= (r - l + 1) * sum_mu(n / l);
    }
    return mp[n] = ans;
}
