// NTT 多项式乘法
void ntt(int *a, int n, int op) {
    for (int i = 1, j = n >> 1; i < n - 1; i++) {
        if (i < j) swap(a[i], a[j]);
        int k = n >> 1;
        while (j >= k) j -= k, k >>= 1;
        j += k;
    }
    for (int len = 2; len <= n; len <<= 1) {
        int wn = qpow(G, (MOD - 1) / len, MOD);
        if (op == -1) wn = qpow(wn, MOD - 2, MOD);
        for (int i = 0; i < n; i += len) {
            int w = 1;
            for (int j = 0; j < len / 2; j++) {
                int u = a[i + j], v = 1LL * w * a[i + j + len / 2] % MOD;
                a[i + j] = (u + v) % MOD;
                a[i + j + len / 2] = (u - v + MOD) % MOD;
                w = 1LL * w * wn % MOD;
            }
        }
    }
    if (op == -1) {
        int inv_n = qpow(n, MOD - 2, MOD);
        for (int i = 0; i < n; i++) a[i] = 1LL * a[i] * inv_n % MOD;
    }
}

// 拉格朗日插值
long long lagrange(int n, long long *x, long long *y, long long k) {
    long long ans = 0;
    for (int i = 1; i <= n; i++) {
        long long s1 = 1, s2 = 1;
        for (int j = 1; j <= n; j++) {
            if (i == j) continue;
            s1 = s1 * (k - x[j]) % MOD;
            s2 = s2 * (x[i] - x[j]) % MOD;
        }
        ans = (ans + y[i] * s1 % MOD * qpow(s2, MOD - 2, MOD)) % MOD;
    }
    return (ans + MOD) % MOD;
}
```

